 104     use std::sync::atomic::{AtomicBool, Ordering};
 105     use std::sync::Arc;
 106 
 107     use signal_hook::consts::SIGINT;
 108 
 109     /// Ctrl-C in a line-mode editor reaches this process too: as Git's `launch_editor` does, ignore SIGINT while the
 110     /// editor runs and let its exit status decide. Dropping this gives SIGINT its default action back.
 111     pub struct Guard(Arc<AtomicBool>);
 112 
 113     pub fn enter() -> std::io::Result<Guard> {
 114         let default_action = Arc::new(AtomicBool::new(false));
 115         signal_hook::flag::register_conditional_default(SIGINT, Arc::clone(&default_action))?;
 116         Ok(Guard(default_action))
 117     }
 118 
 119     impl Drop for Guard {
 120         fn drop(&mut self) {
 121             self.0.store(true, Ordering::SeqCst);
 122         }
 123     }
 124 }
