 33 #[derive(Debug)]
 34 struct FrameState {
 35     /// terminal size when the frame was rendered
 36     pub terminal_size: TerminalSize,
 37     /// resulting frame size
 38     pub frame_size: Dimension,
 39     /// position to put cursor after writing all present content
 40     pub expected_cursor_position: Option<Position>,
 41     /// content and pre-calculated hashes for each rendered line
 42     /// the length of this vector should be equal to frame_size.height
 43     pub finished_rows: Vec<FrameRow>,
 44     pub current_styled: Styled<String>,
 45     pub current_line: Vec<Styled<String>>,
 46     pub current_line_width: u16,
 47     pub current_line_hasher: DefaultHasher,
 48 }
 49 
 50 impl FrameState {
 51     pub fn new(terminal_size: TerminalSize) -> Self {
 52         Self {
 53             terminal_size,
 54             frame_size: Dimension::new(0, 0),
 55             finished_rows: Vec::new(),
 56             current_styled: Styled::default(),
 57             current_line: Vec::new(),
 58             current_line_hasher: DefaultHasher::default(),
 59             current_line_width: 0,
 60             expected_cursor_position: None,
 61         }
 62     }
 63 
 64     pub fn write(&mut self, value: &Styled<impl AsRef<str> + Display>) {
 65         self.current_styled.style = value.style;
 66 
 67         for piece in value.content.ansi_aware_chars() {
 68             piece.hash(&mut self.current_line_hasher);
 69             value.style.hash(&mut self.current_line_hasher);
 70 
 71             let current_char = match piece {
 72                 AnsiAwareChar::Char(c) => c,
 73                 AnsiAwareChar::AnsiEscapeSequence(seq) => {
 74                     // we don't care for escape sequences when calculating cursor position
 75                     // and box size
 76                     self.current_styled.content.push_str(seq);
 77                     continue;
 78                 }
 79             };
 80 
 81             if current_char == '\n' {
 82                 self.finish_line();
 83                 continue;
 84             }
 85 
 86             let remaining_width_space = self
 87                 .terminal_size
 88                 .width()
 89                 .saturating_sub(self.current_line_width);
 90             let character_length = UnicodeWidthChar::width(current_char).unwrap_or(0) as u16;
 91 
 92             if character_length > remaining_width_space {
 93                 // the character will (probably) not fit into the current line
 94                 self.finish_line();
 95             }
 96 
 97             self.current_line_width = self.current_line_width.saturating_add(character_length);
 98             self.current_styled.content.push(current_char);
 99         }
100 
101         if !self.current_styled.content.is_empty() {
102             self.current_line
103                 .push(std::mem::take(&mut self.current_styled));
104         }
105     }
106 
107     pub fn mark_cursor_position(&mut self, offset: isize) {
108         let row = self.finished_rows.len() as u16;
109         let col = self.current_line_width.saturating_add(offset as u16);
110 
111         let row_offset = col / self.terminal_size.width();
112         let row = row + row_offset;
113         let col = col % self.terminal_size.width();
114 
115         self.expected_cursor_position = Some(Position { row, col });
116     }
117 
118     pub fn finish(&mut self) {
119         self.finish_line();
120     }
121 
122     pub fn resize_if_needed(&mut self, new_size: TerminalSize) {
123         if new_size == self.terminal_size {
124             return;
125         }
126 
127         let mut new_state = Self::new(new_size);
128         for row in &self.finished_rows {
129             for styled in row.get_content() {
130                 new_state.write(styled);
131             }
132             new_state.finish_line();
133         }
134         for styled in &self.current_line {
135             new_state.write(styled);
136         }
137         new_state.finish_line();
138 
139         *self = new_state;
140     }
141 
142     fn finish_line(&mut self) {
143         let current_styled = std::mem::take(&mut self.current_styled);
144         self.current_styled.style = current_styled.style;
145 
146         if !current_styled.content.is_empty() || !current_styled.style.is_empty() {
147             self.current_line.push(current_styled);
148         }
149 
150         let hasher = std::mem::take(&mut self.current_line_hasher);
151         let content = std::mem::take(&mut self.current_line);
152 
153         if content.is_empty() {
154             return;
155         }
156 
157         self.finished_rows
158             .push(FrameRow::new(content, hasher.finish()));
159 
160         self.frame_size = Dimension::new(
161             self.frame_size.width().max(self.current_line_width),
162             self.finished_rows.len() as u16,
163         );
164 
165         if !self.current_styled.style.is_empty() {
166             self.current_styled
167                 .style
168                 .hash(&mut self.current_line_hasher);
169         }
170 
171         self.current_line_width = 0;
172     }
173 }
