190     terminal: T,
191     cursor_position: Position,
192     state: RenderState,
193 }
194 
195 impl<T> FrameRenderer<T>
196 where
197     T: Terminal,
198 {
199     pub fn new(terminal: T) -> io::Result<Self> {
200         Ok(Self {
201             terminal,
202             cursor_position: Position::default(),
203             state: RenderState::Initial,
204         })
205     }
206 
207     pub fn write(&mut self, value: impl Display) -> io::Result<()> {
208         self.write_styled(Styled::new(value))
209     }
210 
211     pub fn write_styled(&mut self, value: Styled<impl Display>) -> io::Result<()> {
212         match &mut self.state {
213             RenderState::Rendered(_) | RenderState::Initial => {}
214             RenderState::ActiveRender { current_frame, .. } => {
215                 // here we are converting from a generic impl Display to String
216                 // because we are storing the string content in the frame (we can't store a ref to an object, for example).
217                 //
218                 // we pay a little bit in memory/cpu usage for this so we can
219                 // calculate incremental rendering and cursor position on-the-fly.
220                 let formatted = format!("{}", value.content);
221                 let value = value.with_content(formatted);
222 
223                 current_frame.write(&value);
224             }
225         }
226 
227         Ok(())
228     }
229 
230     pub fn mark_cursor_position(&mut self, offset: isize) {
231         match &mut self.state {
232             RenderState::Rendered(_) | RenderState::Initial => {}
233             RenderState::ActiveRender { current_frame, .. } => {
234                 current_frame.mark_cursor_position(offset);
235             }
236         }
237     }
238 
239     pub fn start_frame(&mut self) -> io::Result<()> {
240         let terminal_size = self.refresh_terminal_size();
241 
242         self.state = match std::mem::replace(&mut self.state, RenderState::Initial) {
243             RenderState::Initial => RenderState::ActiveRender {
244                 last_rendered_frame: FrameState::new(terminal_size),
245                 current_frame: FrameState::new(terminal_size),
246             },
247 
248             RenderState::Rendered(last_rendered_frame) => RenderState::ActiveRender {
249                 last_rendered_frame,
250                 current_frame: FrameState::new(terminal_size),
251             },
252 
253             RenderState::ActiveRender {
254                 last_rendered_frame,
255                 current_frame,
256             } => RenderState::ActiveRender {
257                 last_rendered_frame,
258                 current_frame,
259             },
260         };
261 
262         Ok(())
263     }
264 
265     pub fn finish_current_frame(&mut self, add_empty_line: bool) -> io::Result<()> {
266         let (last_rendered_frame, mut current_frame) = match std::mem::take(&mut self.state) {
267             RenderState::Rendered(_) | RenderState::Initial => {
268                 return Ok(());
269             }
270             RenderState::ActiveRender {
271                 last_rendered_frame,
272                 current_frame,
273             } => (last_rendered_frame, current_frame),
274         };
275 
276         current_frame.finish();
277 
278         let rows_to_iterate = std::cmp::max(
279             last_rendered_frame.frame_size.height(),
280             current_frame.frame_size.height(),
281         );
282 
283         self.terminal.cursor_hide()?;
284         self.move_cursor_to(Position { row: 0, col: 0 })?;
285 
286         for i in 0..rows_to_iterate {
287             let last_row = last_rendered_frame.finished_rows.get(i as usize);
288             let current_row = current_frame.finished_rows.get(i as usize);
289 
290             match (last_row, current_row) {
291                 (Some(last_row), Some(current_row)) => {
292                     if last_row.hash() != current_row.hash() {
293                         for styled in current_row.get_content() {
294                             self.terminal.write_styled(styled)?;
295                         }
296                         self.terminal.clear_until_new_line()?;
297                     }
298                 }
299                 (Some(_), None) => {
300                     self.terminal.clear_line()?;
301                 }
302                 (None, Some(current_row)) => {
303                     for styled in current_row.get_content() {
304                         self.terminal.write_styled(styled)?;
305                     }
306                 }
307                 (None, None) => {
308                     // unreachable, but we don't want to panic live :)
309                     #[cfg(test)]
310                     unreachable!(
311                         "frame_size should never be larger then finished_rows for both frames"
312                     )
313                 }
314             }
315 
316             self.terminal.write("\r")?;
317             self.cursor_position.col = 0;
318             if i + 1 < rows_to_iterate {
319                 self.terminal.write("\n")?;
320                 self.cursor_position.row += 1;
321             }
322         }
323 
324         if add_empty_line {
325             self.terminal.write("\n")?;
326             self.cursor_position.row += 1;
327         }
328 
329         if let Some(expected_cursor_position) = current_frame.expected_cursor_position {
330             self.move_cursor_to(expected_cursor_position)?;
331         }
332 
333         self.terminal.cursor_show()?;
334         self.terminal.flush()?;
335 
336         self.state = RenderState::Rendered(current_frame);
337 
338         Ok(())
339     }
340 
341     fn move_cursor_to_end_position(&mut self) -> io::Result<()> {
342         self.refresh_terminal_size();
343 
344         let last_rendered = match &mut self.state {
345             RenderState::Initial => return Ok(()),
346             RenderState::ActiveRender {
347                 last_rendered_frame,
348                 ..
349             }
350             | RenderState::Rendered(last_rendered_frame) => last_rendered_frame,
351         };
352 
353         let end_position = Position {
354             col: 0,
355             row: last_rendered.frame_size.height(),
356         };
357 
358         self.move_cursor_to(end_position)?;
359 
360         Ok(())
361     }
362 
363     fn move_cursor_to(&mut self, position: Position) -> io::Result<()> {
364         let current_cursor_position = self.cursor_position;
365 
366         match current_cursor_position.row.cmp(&position.row) {
367             Ordering::Greater => {
368                 self.terminal
369                     .cursor_up(current_cursor_position.row - position.row)?;
370             }
371             Ordering::Less => {
372                 self.terminal
373                     .cursor_down(position.row - current_cursor_position.row)?;
374             }
375             Ordering::Equal => {}
376         }
377 
378         match current_cursor_position.col.cmp(&position.col) {
379             Ordering::Greater => {
380                 self.terminal
381                     .cursor_left(current_cursor_position.col - position.col)?;
382             }
383             Ordering::Less => {
384                 self.terminal
385                     .cursor_right(position.col - current_cursor_position.col)?;
386             }
387             Ordering::Equal => {}
388         }
389 
390         self.cursor_position = position;
391 
392         Ok(())
393     }
394 
395     fn refresh_terminal_size(&mut self) -> TerminalSize {
396         // not properly handling resizes is better than panicking, so when
397         // getting the terminal size fails, we assume we're on a terminal
398         // that will always have enough space
399         let terminal_size = self
400             .terminal
401             .get_size()
402             .unwrap_or_default()
403             .unwrap_or_default();
404 
405         if terminal_size.width() < self.cursor_position.col {
406             let new_line_offset = self.cursor_position.col / terminal_size.width();
407             let new_col = self.cursor_position.col % terminal_size.width();
408             self.cursor_position = Position {
409                 row: self.cursor_position.row + new_line_offset,
410                 col: new_col,
411             };
412         }
413 
414         match &mut self.state {
415             RenderState::Initial => {}
416             RenderState::ActiveRender {
417                 current_frame,
418                 last_rendered_frame,
419             } => {
420                 last_rendered_frame.resize_if_needed(terminal_size);
421                 current_frame.resize_if_needed(terminal_size);
422             }
423             RenderState::Rendered(last_rendered_frame) => {
424                 last_rendered_frame.resize_if_needed(terminal_size);
425             }
426         };
427 
428         terminal_size
429     }
430 }
431 
432 impl<T> Drop for FrameRenderer<T>
433 where
434     T: Terminal,
435 {
436     fn drop(&mut self) {
437         let _unused = self.move_cursor_to_end_position();
438         let _unused = self.terminal.cursor_show();
439         let _unused = self.terminal.flush();
440     }
441 }
