464         renderer.write("\x1b[1;31mWhat\x1b[0m is your name?")?;
465         renderer.finish_current_frame(false)?;
466 
467         let terminal = &mut renderer.terminal;
468 
469         terminal.match_text("Hello");
470         terminal.match_text("World");
471         terminal.match_text("\r");
472         terminal.match_text("\n");
473         terminal.match_text("\x1b[1;31mWhat\x1b[0m is your name?");
474 
