478     #[test]
479     fn cursor_position_multiline_overflow() -> InquireResult<()> {
480         use super::RenderState;
481 
482         let mut output = VecDeque::new();
483         // Set narrow terminal width to force text wrapping
484         let terminal = MockTerminal::new(&mut output).with_size(TerminalSize::new(10, 10).unwrap());
485         let mut renderer = FrameRenderer::new(terminal)?;
486 
487         renderer.start_frame()?;
488 
489         // Write exactly 10 characters to fill first line
490         renderer.write("hello worl")?;
491 
492         // Test case 1: offset that spans multiple rows
493         // Current line width = 10, offset = 15 means total = 25
494         // This should put cursor at row=2, col=5 (25 / 10 = 2 extra rows, 25 % 10 = 5)
495         renderer.mark_cursor_position(15);
496 
497         let expected_position = match &renderer.state {
498             RenderState::ActiveRender { current_frame, .. } => {
499                 current_frame.expected_cursor_position
500             }
501             _ => None,
502         };
503 
504         if let Some(pos) = expected_position {
505             assert_eq!(
506                 pos.row, 2,
507                 "Expected cursor row to be 2 when spanning multiple lines"
508             );
509             assert_eq!(pos.col, 5, "Expected cursor col to be 5 after wrapping");
510         } else {
511             panic!("Expected cursor position to be set");
512         }
513 
514         // Test case 2: exact multiple of terminal width
515         // offset = 20 means total = 30, should be row=3, col=0
516         renderer.mark_cursor_position(20);
517 
518         let expected_position = match &renderer.state {
519             RenderState::ActiveRender { current_frame, .. } => {
520                 current_frame.expected_cursor_position
521             }
522             _ => None,
523         };
524 
525         if let Some(pos) = expected_position {
526             assert_eq!(pos.row, 3, "Expected cursor row to be 3 for exact multiple");
527             assert_eq!(pos.col, 0, "Expected cursor col to be 0 for exact multiple");
528         } else {
529             panic!("Expected cursor position to be set");
530         }
531 
532         // Test case 3: spanning multiple lines
533         // offset = 99 means total = 109, should be row=10, col=9
534         renderer.mark_cursor_position(99);
535 
536         let expected_position = match &renderer.state {
537             RenderState::ActiveRender { current_frame, .. } => {
538                 current_frame.expected_cursor_position
539             }
540             _ => None,
541         };
542 
543         if let Some(pos) = expected_position {
544             assert_eq!(
545                 pos.row, 10,
546                 "Expected cursor row to be 3 for exact multiple"
547             );
548             assert_eq!(pos.col, 9, "Expected cursor col to be 0 for exact multiple");
549         } else {
550             panic!("Expected cursor position to be set");
551         }
552 
553         Ok(())
