101 /// `init` against explicit terminal state, prompter, output streams, and command runner.
102 pub fn run<R: CommandRunner>(
103     args: InitArgs,
104     global: &GlobalArgs,
105     interactive: bool,
106     prompter: &mut dyn Prompter,
107     out: &mut dyn Write,
108     err: &mut dyn Write,
109     runner: &R,
110 ) -> Result<ExitCode, CliError> {
111     validate_flags(&args)?;
112     // A repository whose manifests all sit in subdirectories has no root yet: init makes the Git toplevel one.
113     let (root, no_root) = match workspace_root(global, runner) {
114         Ok(root) => (root, None),
115         Err(CliError::Locate(LocateError::WorkspaceRootNotFound { start, toplevel })) => (
116             toplevel.clone(),
117             Some(LocateError::WorkspaceRootNotFound { start, toplevel }),
118         ),
119         Err(error) => return Err(error),
120     };
121     let locator = IgnoreWalkLocator::new(&root);
122     if args.workflow && scaffold::is_initialized(&root)? {
123         // Answers feed callisto.toml, which stays as it is: refuse them rather than drop them.
124         // The forge and product flags already require an artifact target.
125         if args.versioning.is_some() || !args.artifact_targets.is_empty() {
126             return Err(GraphError::InitAlreadyInitialized {
127                 path: root.join("callisto.toml"),
128             }
129             .into());
130         }
131         return run_workflow_only(&root, &locator, global, out, err, runner);
132     }
133     let facts = scaffold::detect(&root, &locator, runner)?;
134     if let Some(error) = no_root.filter(|_| facts.packages.is_empty()) {
135         return Err(error.into());
136     }
137     let json = global.format == OutputFormat::Json;
138     // JSON keeps stdout for the report.
139     let human: &mut dyn Write = if json { &mut *err } else { &mut *out };
140     write_facts(&facts, human)?;
141 
142     if facts.origin.is_none() {
143         if args.workflow {
144             return Err(CliError::InitFlagRequiresOrigin { flag: "workflow" });
145         }
146         if !args.artifact_targets.is_empty() {
147             return Err(CliError::InitFlagRequiresOrigin {
148                 flag: "artifact-target",
149             });
150         }
151     }
152     if !interactive && !args.yes {
153         let mut missing = vec!["--yes"];
154         missing.extend(missing_flags(&args, &facts));
155         return Err(CliError::InitRequiresYes { missing });
156     }
157     if args.yes {
158         let missing = missing_flags(&args, &facts);
159         if !missing.is_empty() {
160             return Err(CliError::InitMissingFlags { missing });
161         }
162     }
163     let prompting = interactive && !args.yes;
164     let migration = changesets::migrate(&facts.root, &facts);
165     // A dry run writes nothing, so it previews with the warning instead.
166     if !migration.public_scoped.is_empty() && !args.yes && !global.dry_run {
167         return Err(CliError::InitChangesetsAccess {
168             packages: migration.public_scoped,
169         });
170     }
171     let mut answers = collect_answers(&args, &facts, prompting, prompter)?;
172 
173     let mut diagnostics = migration.diagnostics.clone();
174     diagnostics.extend(migration.apply_fixed_groups(&mut answers));
175     if facts.origin.is_none() {
176         writeln!(human, "{ORIGIN_MISSING_NOTE}")?;
177         diagnostics.push(callisto_model::Diagnostic {
178             code: callisto_model::DiagnosticCode::InitOriginMissing,
179             severity: callisto_model::DiagnosticSeverity::Warning,
180             message: ORIGIN_MISSING_NOTE.to_owned(),
181             package: None,
182             path: None,
183             escalated_by: None,
184             governed_by: None,
185         });
186     }
187     let shape = match scaffold::workflow_shape(&facts, answers.binaries.is_some()) {
188         Err(reason) if args.workflow => {
189             return Err(GraphError::InitWorkflowUnsupported {
190                 reason: reason.to_string(),
191             }
192             .into());
193         }
194         Err(reason) => {
195             let note = workflow_unsupported_note(reason);
196             writeln!(human, "{note}")?;
197             diagnostics.push(callisto_model::Diagnostic {
198                 code: callisto_model::DiagnosticCode::WorkflowGenerationUnsupported,
199                 severity: callisto_model::DiagnosticSeverity::Warning,
200                 message: note,
201                 package: None,
202                 path: None,
203                 escalated_by: None,
204                 governed_by: None,
205             });
206             None
207         }
208         Ok(shape) => Some(shape),
209     };
210     let want_workflow = match shape {
211         None => false,
212         Some(_) if args.workflow => true,
213         Some(_) if args.no_workflow => false,
214         Some(_) if prompting && facts.origin.is_some() => prompter.confirm(WORKFLOW_PROMPT, true)?,
215         // The workflow is GitHub Actions, so only a GitHub origin gets it unasked.
216         Some(_) => facts.origin_repository.is_some(),
217     };
218     // A workflow nobody asked for (the default) never fails `init`: if it cannot be built, say why and go on.
219     let asked_for_workflow = args.workflow || prompting;
220     let workflow = match shape.filter(|_| want_workflow) {
221         Some(shape) => match build_workflow(&facts, shape, migration.base_branch.as_ref(), runner, human) {
222             Ok(built) => Some(built),
223             Err(error) if !asked_for_workflow => {
224                 let note =
225                     format!("Skipping the GitHub Actions workflow: {error}. Run `callisto init --workflow` to retry.");
226                 writeln!(human, "{note}")?;
227                 diagnostics.push(callisto_model::Diagnostic {
228                     code: callisto_model::DiagnosticCode::WorkflowGenerationUnsupported,
229                     severity: callisto_model::DiagnosticSeverity::Warning,
230                     message: note,
231                     package: None,
232                     path: None,
233                     escalated_by: None,
234                     governed_by: None,
235                 });
236                 None
237             }
238             Err(error) => return Err(error),
239         },
240         None => None,
241     };
242     if workflow.is_none() {
243         diagnostics.extend(migration.base_branch_unused());
244     }
245 
246     let config = scaffold::render_config(&facts, &answers);
247     let plan = if facts.has_commit {
248         Some(scaffold::preview(&facts, &config, &locator, runner)?)
249     } else {
250         None
251     };
252     if config
253         .lines()
254         .all(|line| line.trim().is_empty() || line.trim_start().starts_with('#'))
255     {
256         writeln!(human, "\ncallisto.toml: no settings needed, the defaults apply.")?;
257     } else {
258         writeln!(human, "\ncallisto.toml:\n{config}")?;
259     }
260     match plan {
261         Some(plan) => {
262             writeln!(human, "First release preview (`callisto release --dry-run`):")?;
263             super::release::write_release_preview(plan.as_ref(), OutputFormat::Text, human)?;
264         }
265         None => writeln!(human, "{NO_COMMITS}")?,
266     }
267     if let Some((workflow, _)) = &workflow {
268         writeln!(
269             human,
270             "\n{}:\n{workflow}",
271             scaffold::workflow_path(&facts.root).display()
272         )?;
273     }
274 
275     // Computed before any write, so the `.changeset/README.md` existence check sees disk state as-is.
276     let files = scaffold::init_files(&facts.root, workflow.is_some())?;
277     let mut report = if global.dry_run {
278         InitReport {
279             schema_version: SCHEMA_VERSION,
280             initialized: false,
281             config_path: facts.root.join("callisto.toml"),
282             config,
283             files,
284             diagnostics: Vec::new(),
285         }
286     } else {
287         if prompting && !prompter.confirm(WRITE_PROMPT, true)? {
288             writeln!(human, "{}", tty::CANCELLED)?;
289             return Ok(ExitCode::SUCCESS);
290         }
291         let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).expect("non-dry-run permits writes");
292         let mut report = scaffold::write(&facts.root, &config, &permit)?;
293         if let Some((workflow, branch)) = &workflow {
294             scaffold::write_workflow(&facts.root, workflow, &permit)?;
295             diagnostics.push(announce_workflow(human, &facts, branch)?);
296         }
297         report.files = files;
298         report
299     };
300     report.diagnostics.extend(diagnostics);
301     if json {
302         emit_report(&mut &mut *out, &report, global.dry_run)?;
303     } else {
304         render::render_init(&report, &mut &mut *out)?;
305     }
306     Ok(ExitCode::SUCCESS)
307 }
