309 /// Prints what a written workflow means and what to do next; the same text is recorded as a diagnostic.
310 fn announce_workflow(
311     human: &mut dyn Write,
312     facts: &InitFacts,
313     branch: &BranchName,
314 ) -> Result<callisto_model::Diagnostic, CliError> {
315     let note = merge_publishes_note(branch);
316     writeln!(human, "{note}")?;
317     writeln!(human, "{}", next_steps_note(&scaffold::registry_secret_names(facts)))?;
318     Ok(callisto_model::Diagnostic {
319         code: callisto_model::DiagnosticCode::WorkflowMergePublishes,
320         severity: callisto_model::DiagnosticSeverity::Info,
321         message: note,
322         package: None,
323         path: None,
324         escalated_by: None,
325         governed_by: None,
326     })
327 }
