329 /// `init --workflow` in a workspace that already has `callisto.toml`: writes only the workflow.
330 fn run_workflow_only<R: CommandRunner>(
331     root: &std::path::Path,
332     locator: &IgnoreWalkLocator,
333     global: &GlobalArgs,
334     out: &mut dyn Write,
335     err: &mut dyn Write,
336     runner: &R,
337 ) -> Result<ExitCode, CliError> {
338     let facts = scaffold::detect_initialized(root, locator, runner)?;
339     let json = global.format == OutputFormat::Json;
340     let human: &mut dyn Write = if json { &mut *err } else { &mut *out };
341     write_facts(&facts, human)?;
342     if facts.origin.is_none() {
343         return Err(CliError::InitFlagRequiresOrigin { flag: "workflow" });
344     }
345     let shape =
346         scaffold::workflow_shape(&facts, scaffold::existing_config_ships_binaries(&facts.root)?).map_err(|reason| {
347             GraphError::InitWorkflowUnsupported {
348                 reason: reason.to_string(),
349             }
350         })?;
351     let base_branch = changesets::base_branch(root);
352     let (workflow, branch) = build_workflow(&facts, shape, base_branch.as_ref(), runner, human)?;
353     writeln!(
354         human,
355         "\n{}:\n{workflow}",
356         scaffold::workflow_path(&facts.root).display()
357     )?;
358     let mut diagnostics = Vec::new();
359     if !global.dry_run {
360         let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).expect("non-dry-run permits writes");
361         scaffold::write_workflow(&facts.root, &workflow, &permit)?;
362         diagnostics.push(announce_workflow(human, &facts, &branch)?);
363     }
364     let config_path = facts.root.join("callisto.toml");
365     let config = callisto_model::strict_fs::read_optional(&config_path)
366         .map_err(|error| GraphError::InitIo {
367             path: config_path.clone(),
368             message: error.to_string(),
369         })?
370         .unwrap_or_default();
371     let report = InitReport {
372         schema_version: SCHEMA_VERSION,
373         initialized: !global.dry_run,
374         config_path,
375         config,
376         files: vec![scaffold::workflow_path(&facts.root)],
377         diagnostics,
378     };
379     if json {
380         emit_report(&mut &mut *out, &report, global.dry_run)?;
381     } else {
382         render::render_init(&report, &mut &mut *out)?;
383     }
384     Ok(ExitCode::SUCCESS)
385 }
