387 /// The workflow text and the default branch it triggers on.
388 fn build_workflow<R: CommandRunner>(
389     facts: &InitFacts,
390     shape: scaffold::WorkflowShape,
391     base_branch: Option<&BranchName>,
392     runner: &R,
393     human: &mut dyn Write,
394 ) -> Result<(String, BranchName), CliError> {
395     scaffold::ensure_workflow_absent(&facts.root)?;
396     let branch = match base_branch {
397         Some(name) => scaffold::DefaultBranch {
398             name: name.clone(),
399             source: scaffold::DefaultBranchSource::ChangesetsBaseBranch,
400         },
401         None => scaffold::default_branch(runner, &facts.root),
402     };
403     writeln!(human, "  default branch: {} (from {})", branch.name, branch.source)?;
404     let version = semver::Version::parse(env!("CARGO_PKG_VERSION")).expect("Cargo package versions are semver");
405     let commit = scaffold::resolve_release_commit(runner, &facts.root, &version)?;
406     let content = scaffold::render_workflow(facts, shape, &branch.name, &commit, &version);
407     Ok((content, branch.name))
408 }
