 461 fn collect_answers(
 462     args: &InitArgs,
 463     facts: &InitFacts,
 464     prompting: bool,
 465     prompter: &mut dyn Prompter,
 466 ) -> Result<InitAnswers, CliError> {
 467     let versioning = match args.versioning {
 468         Some(InitVersioning::Fixed) => Versioning::Fixed,
 469         Some(InitVersioning::Independent) => Versioning::Independent,
 470         // Fixed and independent mean the same for one package, so only several packages are asked.
 471         None if prompting && facts.packages.len() > 1 => {
 472             let choices: Vec<String> = VERSIONING_CHOICES.iter().map(|choice| (*choice).to_owned()).collect();
 473             match prompter.select(VERSIONING_PROMPT, &choices)? {
 474                 0 => Versioning::Independent,
 475                 _ => Versioning::Fixed,
 476             }
 477         }
 478         None => Versioning::Independent,
 479     };
 480     let no_binaries = InitAnswers {
 481         versioning,
 482         binaries: None,
 483         fixed_groups: Vec::new(),
 484     };
 485 
 486     let binaries: Vec<&InitPackage> = facts.binary_packages().collect();
 487     if binaries.is_empty() && !args.artifact_targets.is_empty() {
 488         if let Some(package) = facts.unsupported_artifact_packages().next() {
 489             return Err(GraphError::InitUnsupportedArtifactBuilder {
 490                 package: package.id.clone(),
 491                 ecosystem: package
 492                     .id
 493                     .split_once('/')
 494                     .map_or("unknown", |(ecosystem, _)| ecosystem)
 495                     .to_owned(),
 496             }
 497             .into());
 498         }
 499         return Err(GraphError::InitNoBinaryPackage.into());
 500     }
 501     let requested_product = args
 502         .product_package
 503         .as_deref()
 504         .map(|name| facts.product_package(name))
 505         .transpose()?;
 506     if binaries.is_empty() {
 507         return Ok(no_binaries);
 508     }
 509     // No `origin`: the forge question below has nothing to validate a repository against, so
 510     // shipping is never offered (skips straight to `no_binaries`); `--artifact-target` without
 511     // `origin` is already rejected up front in `run`.
 512     let ship = !args.artifact_targets.is_empty()
 513         || (facts.origin.is_some() && prompting && prompter.confirm(SHIP_PROMPT, false)?);
 514     if !ship {
 515         return Ok(no_binaries);
 516     }
 517     // A release goes to origin's GitHub repository, so shipping needs one.
 518     if facts.origin_repository.is_none() {
 519         return Err(GraphError::ReleaseForgeRepositoryMissing.into());
 520     }
 521 
 522     let product = match (requested_product, binaries.as_slice()) {
 523         (Some(product), _) => product,
 524         (None, [only]) => only,
 525         (None, _) if prompting => {
 526             let ids: Vec<String> = binaries.iter().map(|package| package.id.clone()).collect();
 527             binaries[prompter.select(PRODUCT_PROMPT, &ids)?]
 528         }
 529         (None, _) => return Err(missing("--product-package")),
 530     };
 531 
 532     let targets = if args.artifact_targets.is_empty() {
 533         loop {
 534             let answer = prompter.input(TARGETS_PROMPT, None)?;
 535             let targets: Vec<String> = answer.split(',').map(str::trim).map(str::to_owned).collect();
 536             if targets.iter().all(|target| target.is_empty()) {
 537                 // Nothing meaningful submitted: re-ask rather than error.
 538                 continue;
 539             }
 540             break targets;
 541         }
 542     } else {
 543         args.artifact_targets.clone()
 544     };
 545     let targets = scaffold::validate_targets(&targets)?;
 546 
 547     Ok(InitAnswers {
 548         versioning,
 549         binaries: Some(BinaryRelease {
 550             product: product.id.clone(),
 551             targets,
 552         }),
 553         fixed_groups: Vec::new(),
 554     })
 555 }
